BEGINNING-OF-PROGRAM
    DEFINE-NEW-INSTRUCTION turnright AS
    BEGIN
        turnleft;
        turnleft;
        turnleft
    END
    DEFINE-NEW-INSTRUCTION jump-hurdle AS
    BEGIN
        turnleft;
        move;
        turnright;
        move;
        turnright;
        move;
        turnleft
    END
    BEGINNING-OF-EXECUTION
        WHILE not-next-to-a-beeper DO
        BEGIN
            IF front-is-clear THEN
                move
            ELSE
                jump-hurdle
        END
        pickbeeper;
        turnoff
    END-OF-EXECUTION
END-OF-PROGRAM
